using System.Buffers.Binary;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text.Json;
using UnifiedRgb.Devices.AsusRog;
using UnifiedRgb.Host.Services;

namespace UnifiedRgb.Host.Tests;

public sealed partial class RogNativeMenuSourceTests
{
    // Exact Root-exported final linked-C fixture, embedded so tests need no repository/TASK ancestry or device access.
    // Pins are fixture provenance only; production capability admission never checks image/build hashes.
    private const string D50ProducerBase64 = "";

    private static JsonDocument D50Producer() => JsonDocument.Parse(Convert.FromBase64String(D50ProducerBase64));

    public static IEnumerable<object[]> D50Contexts()
    {
        using var document = D50Producer();
        return document.RootElement.GetProperty("cases").EnumerateArray()
            .Select(c => new object[] { c.GetProperty("mode").GetByte(), c.GetProperty("profile").GetByte(), c.GetProperty("transport").GetByte() }).ToArray();
    }

    private static JsonElement D50Case(JsonDocument document, byte mode, byte profile, byte transport) =>
        document.RootElement.GetProperty("cases").EnumerateArray().Single(c => c.GetProperty("mode").GetByte() == mode
            && c.GetProperty("profile").GetByte() == profile && c.GetProperty("transport").GetByte() == transport);

    private static byte[] D50Bytes(JsonElement item, string name) => Convert.FromHexString(item.GetProperty(name).GetString()!);

    [Fact]
    public void Codex_D50_fixture_pins_final_linked_image_ELF_and_honest_proof_tier()
    {
        Convert.ToHexString(SHA256.HashData(Convert.FromBase64String(D50ProducerBase64)))
            .Should().Be("745ECDB29C9FFEADA88D87F17BDCA61455B28FA93F2ECC6A78AC3433C7A9527D");
        using var document = D50Producer(); var root = document.RootElement;
        root.GetProperty("candidateSha256").GetString().Should().Be("8af76c142db0fc621c2c79a054c121e8964d0c938ce473efec74c1b1ea979939");
        root.GetProperty("elfSha256").GetString().Should().Be("73fef3c9f2d918f6d41b367fd75346b8e3e6ea2cca115f3eba8f13748437494c");
        root.GetProperty("classification").GetString().Should().Be("FINAL_D50_LINKED_THUMB_POLICY_PAYLOADS_CONTROLLED_CONTEXT_NOT_HARDWARE");
        root.GetProperty("calls").GetInt32().Should().Be(192);
        root.GetProperty("cases").GetArrayLength().Should().Be(24);
    }

    [Theory] [MemberData(nameof(D50Contexts))]
    public void Codex_D50_actual_CAP_ARM_neutral_center_boundary_bytes_match_codec_and_state(byte mode, byte profile, byte transport)
    {
        using var document = D50Producer(); var item = D50Case(document, mode, profile, transport);
        var cap = RogNativeMenuCodec.ParseCapability(D50Bytes(item, "capability65"), 0x12, transport);
        var armRequest = D50Bytes(item, "armRequest65");
        var cookie = BinaryPrimitives.ReadUInt64LittleEndian(armRequest.AsSpan(11));
        cap.Mode.Should().Be(mode); cap.Profile.Should().Be(profile); cap.Transport.Should().Be(transport);
        RogNativeMenuCodec.SupportsDedicatedPage(cap).Should().BeTrue();
        RogNativeMenuCodec.ArmRequest(cap, cookie).Should().Equal(armRequest);
        armRequest[25].Should().Be(mode);
        var reply = RogNativeMenuCodec.ParseCapability(D50Bytes(item, "armReply65"), 0x71, transport);
        var state = new RogNativeMenuState(); state.Arm(cap, reply, cookie); state.Matches(reply).Should().BeTrue();
        var kind = RogNativeMenuCodec.ParseNotice(D50Bytes(item, "neutral21"), transport, out var neutral);
        kind.Should().Be(RogNativeNoticeKind.Tagged);
        state.Accept(kind, neutral).Should().Be(RogNativeDecision.Ignore); state.Neutral.Should().BeTrue();
        kind = RogNativeMenuCodec.ParseNotice(D50Bytes(item, "center21"), transport, out var center);
        center.Mode.Should().Be(mode); center.Profile.Should().Be(profile); center.Mask.Should().Be(2);
        state.Accept(kind, center).Should().Be(mode == 9 ? RogNativeDecision.Toggle : RogNativeDecision.Ignore);
        state.Sequence.Should().Be(center.Sequence);
        kind = RogNativeMenuCodec.ParseNotice(D50Bytes(item, "boundary21"), transport, out var boundary);
        boundary.Cookie.Should().Be(0); boundary.Flags.Should().Be(4); boundary.Mode.Should().Be((byte)(19-mode));
        state.Accept(kind, boundary).Should().Be(RogNativeDecision.Disarmed); state.Scope.Should().BeNull();
    }

    [Theory] [InlineData((byte)1)] [InlineData((byte)2)]
    public async Task Codex_D50_actual_center_can_open_once_after_normal_quick_release_without_case_actions(byte transport)
    {
        using var document = D50Producer(); var item = D50Case(document, 10, 0, transport);
        var request = D50Bytes(item, "armRequest65"); var cookie = BinaryPrimitives.ReadUInt64LittleEndian(request.AsSpan(11));
        var time = new SourceClock(); using var input = new Input(time, transport);
        using var io = new Connection(time, transport) { Input = input, DedicatedPage = true, Mode = 10, Profile = 0,
            Epoch = BinaryPrimitives.ReadUInt32LittleEndian(D50Bytes(item, "capability65").AsSpan(15)) };
        var source = new RogNativeMenuSource(Policy(transport), input, input, time, () => cookie);
        var events = new ConcurrentQueue<NativeMenuSourceEvent>(); using var registration = source.Connect(events.Enqueue);
        await using var actor = source.Attach(io); input.Admitted = () => actor.ReceivedNotifications;
        var fake = new CodexLaunchTests.FakeActivator(); Func<Task>? queued = null;
        var scheduled = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        using var coordinator = new CodexLaunchCoordinator(fake, time, schedule: work =>
        {
            queued = async () => { try { await work(); } finally { scheduled.TrySetResult(); } };
            return scheduled.Task;
        });
        source.SetLaunchCoordinator(coordinator); source.RequestCodexEnabled(true);
        await actor.StepAsync(_ => null, default);
        io.Packets.Single(p => p[1] == 0x71 && p[10] == 1).Should().Equal(request);
        input.Send(D50Bytes(item, "neutral21")); input.Send(D50Bytes(item, "center21"));
        // A legitimate release is not a new intent or context change. Its wire bytes differ only in mask/flags/nextsequence.
        var release = D50Bytes(item, "center21"); release[2] = 0; BinaryPrimitives.WriteUInt16LittleEndian(release.AsSpan(19), 3);
        input.Send(release); await input.WaitReads(3); await actor.StepAsync(_ => null, default);
        queued.Should().NotBeNull(); fake.Calls.Should().Be(0); await queued!(); fake.Calls.Should().Be(1);
        source.ControlsRequested.Should().BeFalse(); events.OfType<NativeMenuPress>().Should().BeEmpty();
        events.OfType<NativeMenuSceneBrowse>().Should().BeEmpty(); await coordinator.StopAsync(default);
    }
}
